function clearSpectrogram(){historyCanvas.getContext('2d').clearRect(0,0,600,180);spectroStarted=performance.now();lastSpectro=0;}
function collect(){const sampleRate=ctx?.sampleRate||48000,n=FFT_SIZE;if(playing&&analyser){const wave=new Float32Array(waveAnalyser.fftSize),freq=new Float32Array(analyser.frequencyBinCount);waveAnalyser.getFloatTimeDomainData(wave);analyser.getFloatFrequencyData(freq);const now=ctx.currentTime,count=Math.min(wave.length,Math.max(0,Math.round((now-lastAudioTime)*sampleRate)));for(let i=wave.length-count;i<wave.length;i++){waveHistory[waveWrite]=wave[i];waveWrite=(waveWrite+1)%waveHistory.length;}lastAudioTime=now;return{wave,freq,sampleRate,active:true};}if(source==='synth'){const wave=generateSamples(sound,n,sampleRate);return{wave,freq:spectrum(wave),sampleRate,active:true};}return{wave:new Float32Array(n),freq:new Float32Array(n/2).fill(-160),sampleRate,active:false};}
