function markWaves(){const solo=sound.waves.some(w=>w.solo),audible=sound.waves.filter(w=>!w.mute&&(!solo||w.solo)),maxA=Math.max(0,...(audible.length?audible:sound.waves).map(w=>w.a));$('waveCards').querySelectorAll('.wave-card').forEach((card,i)=>{const w=sound.waves[i];if(!w)return;card.style.setProperty('--welle-ton',`var(--ton-${waveTone(i)})`);card.classList.toggle('solo',w.solo);card.classList.toggle('muted',w.mute||(solo&&!w.solo));card.querySelector('.wave-mute').setAttribute('aria-pressed',String(w.mute));card.querySelector('.wave-solo').setAttribute('aria-pressed',String(w.solo));const d=relativeDb(w.a,maxA);card.querySelector('.wave-db').textContent=sound.waves.length<2?'':d===null?'−∞ dB':(d===0?'0':(d>0?'+':'−')+Math.abs(d))+' dB';});}
// Welle, deren Spitze im Spektrum höchstens 14 px vom Zeiger entfernt liegt (nur Synthesizer).
