// Frequenzachse: logarithmisch bis 20 kHz, linear bis zu einer festen Grenze oder automatisch bis knapp über den höchsten Teilton.
function axisScale(){return experiment?'log':axisChoice;}
function axisLog(){const v=axisScale();return v==='log'||(v==='auto'&&source!=='synth');}
// Auto: knapp über den höchsten Teilton aller klingenden Wellen (unabhängig von Solo, damit die Achse beim Solo ruhig bleibt); nur bei geändertem Klang neu gerechnet.
