function startExperiment(key){if(!Object.hasOwn(experiments,key))return;endBlindIfActive();closeMenus();experiment=key;stage='predict';chooseSource(key==='vowels'?'mic':'synth');const s={waves:[makeWave(220)]};$('timeWindow').value=key==='beats'?'1':'0.025';if(key==='beats')s.waves=[makeWave(220),makeWave(222)];if(key==='missing'){s.waves=[200,400,600,800,1000].map((f,i)=>makeWave(f,'sine',Math.round(100/(i+1))/100));s.waves[0].mute=true;}if(key==='phase')s.waves=[1,2,3,4,5,6].map(n=>makeWave(220*n,'sine',Math.round(100/n)/100));setSound(s);renderExperiment();updateButtons();}
