$('audioFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>50*1024*1024){notice('fileLarge',{},true);return;}const gen=++fileGeneration;stopFile(false);playing=false;fileBuffer=null;fileOffset=0;$('seek').disabled=true;updateButtons();notice('loading');try{await ensureAudio();const buffer=await ctx.decodeAudioData(await file.arrayBuffer());if(gen!==fileGeneration)return;fileBuffer=buffer;delete $('fileName').dataset.i18n;$('fileName').textContent=file.name;$('seek').max=buffer.duration;$('seek').disabled=false;notice('fileReady');updateButtons();dirty=true;}catch{if(gen===fileGeneration)notice('fileError',{},true);}};
$('seek').oninput=async e=>{const wasPlaying=playing;stopFile(false);playing=false;fileOffset=Number(e.target.value);if(wasPlaying)await togglePlay();dirty=true;};$('fileLoop').onchange=e=>{if(fileNode)fileNode.loop=e.target.checked;};
for(const slot of ['A','B']){$('save'+slot).onclick=()=>{ab[slot]=snapshot();updateButtons();notice('abSaved',{slot});};$('load'+slot).onclick=()=>{if(!ab[slot])return;if(source!=='synth')chooseSource('synth');setSound(ab[slot]);notice('abLoaded',{slot});};}
$('savePreset').onclick=()=>{$('presetName').value='';$('saveDialog').showModal();$('presetName').focus();};$('cancelSave').onclick=()=>$('saveDialog').close();$('saveForm').onsubmit=e=>{e.preventDefault();const name=$('presetName').value.trim();if(!name)return;if(storeSaved([...saved,{name,sound:snapshot()}].slice(-50))){$('saveDialog').close();notice('saved');}};$('savedBtn').onclick=()=>{renderSaved();$('savedDialog').showModal();};
$('shareBtn').onclick=()=>{const payload={v:2,sound:snapshot(),experiment,lang};const bytes=new TextEncoder().encode(JSON.stringify(payload));let raw='';bytes.forEach(b=>raw+=String.fromCharCode(b));const encoded=btoa(raw).replaceAll('+','-').replaceAll('/','_').replaceAll('=','');$('shareLink').value=location.origin+location.pathname+'#sound='+encoded;$('shareDialog').showModal();};$('copyLink').onclick=async()=>{try{await navigator.clipboard.writeText($('shareLink').value);notice('copied');$('shareDialog').close();}catch{$('shareLink').select();notice('copyError');}};
$('exportWav').onclick=()=>{const sampleRate=48000,data=generateSamples(sound,sampleRate*3,sampleRate),level=Number($('volume').value);for(let i=0;i<data.length;i++)data[i]*=level*Math.min(1,i/480,(data.length-1-i)/480);const blob=new Blob([wavBuffer(data,sampleRate)],{type:'audio/wav'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mysound-'+(sound.waves.length?Math.min(...sound.waves.map(w=>w.f)):0)+'Hz.wav';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('exported');};
window.addEventListener('pagehide',()=>{sourceGeneration++;disconnectAll();updateButtons();});window.addEventListener('hashchange',loadShare);new ResizeObserver(()=>{dirty=true;}).observe(document.querySelector('.workspace'));
